\set ON_ERROR_STOP on
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is not true then raise exception 'FAIL: %',label; end if; end $$;
create function pg_temp.expect_error(statement text,expected text,label text) returns void language plpgsql as $$ begin begin execute statement; exception when others then if sqlstate=expected then return; end if; raise exception 'FAIL: % expected %, received %',label,expected,sqlstate; end; raise exception 'FAIL: % unexpectedly allowed',label; end $$;
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',false);
insert into public.funding_initiatives(id,kind,name) values('70000000-0000-4000-8000-000000000001','Program','Synthetic Program'),('70000000-0000-4000-8000-000000000002','Event','Synthetic Event');
insert into public.contributions(id,organization_id,contact_id,contribution_date,amount,contribution_type,program_id,event_id,agreement_start,agreement_end,renewal_date,sponsorship_level) values('71000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','2024-01-01',1000,'Cash','70000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000002','2024-01-01','2025-01-01','2025-02-01','Synthetic Gold');
insert into public.cash_receipts(id,contribution_id,received_on,amount) values
('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000001','2024-01-01',100),
('72000000-0000-4000-8000-000000000002','71000000-0000-4000-8000-000000000001','2025-01-01',200.10),
('72000000-0000-4000-8000-000000000003','71000000-0000-4000-8000-000000000001','2025-12-31',0.20);
select pg_temp.assert_true((select cash_received::numeric=300.30 and outstanding::numeric=699.70 and payment_status='Partially Received' from public.contribution_details),'exact partial receipt balances');
select pg_temp.assert_true((public.giving_summary(2025)->>'annual_cash')::numeric=200.30,'calendar year receipts independent of pledge year');
select pg_temp.assert_true((public.giving_summary(2025)->>'prior_cash')::numeric=100,'prior year cash');
select pg_temp.assert_true((public.giving_summary(2025)->>'yoy_percent')::numeric=100.30,'YoY exact percentage');
select pg_temp.assert_true(public.giving_summary(2023)->>'yoy_percent' is null,'zero baseline has no percentage');
select pg_temp.assert_true((public.giving_summary(2025,p_contact_id=>'30000000-0000-4000-8000-000000000002')->>'lifetime_cash')::numeric=0,'contact scope isolates history');
select pg_temp.assert_true((public.giving_summary(2025,p_organization_id=>'20000000-0000-4000-8000-000000000001')->>'lifetime_cash')::numeric=300.30,'organization lifetime cash');
update public.cash_receipts set is_void=true,void_reason='Synthetic correction' where id='72000000-0000-4000-8000-000000000003';
select pg_temp.assert_true((public.giving_summary(2025)->>'annual_cash')::numeric=200.10,'void excluded');
update public.cash_receipts set amount=1200 where id='72000000-0000-4000-8000-000000000002';
select pg_temp.assert_true((select outstanding::numeric=0 and cash_received::numeric=1300 and payment_status='Received' from public.contribution_details),'overpayment stays cash with zero outstanding');
update public.contributions set funding_status='Cancelled';
select pg_temp.assert_true((select pledged::numeric=0 and outstanding::numeric=0 and cash_received::numeric=1300 from public.contribution_details),'cancelled planning stage cannot erase real receipts');
insert into public.contributions(id,contribution_date,amount,contribution_type) values('71000000-0000-4000-8000-000000000002','2025-01-01',9000,'In-Kind');
select pg_temp.assert_true((public.giving_summary(2025)->>'in_kind_declared')::numeric=9000 and (public.giving_summary(2025)->>'annual_cash')::numeric=1200,'in-kind not cash');
select pg_temp.expect_error($q$insert into public.cash_receipts(contribution_id,received_on,amount) values('71000000-0000-4000-8000-000000000002','2025-01-01',50)$q$,'23514','no cash receipts on in-kind');
select pg_temp.expect_error($q$update public.contributions set contribution_type='In-Kind' where id='71000000-0000-4000-8000-000000000001'$q$,'23514','cash history cannot become in-kind');
select pg_temp.expect_error($q$update public.cash_receipts set received_on=public.activity_today()+1$q$,'23514','future receipts denied');
select pg_temp.expect_error($q$update public.cash_receipts set amount=0$q$,'23514','zero receipts denied');
select pg_temp.expect_error($q$update public.cash_receipts set amount=-1$q$,'23514','negative receipts denied');
select pg_temp.expect_error($q$update public.cash_receipts set amount=1.001$q$,'23514','excess precision denied');
select pg_temp.expect_error($q$update public.cash_receipts set amount='NaN'$q$,'23514','NaN denied');
select pg_temp.expect_error($q$update public.cash_receipts set is_void=true,void_reason=null$q$,'23514','void needs reason');
select pg_temp.expect_error($q$update public.cash_receipts set contribution_id='71000000-0000-4000-8000-000000000002'$q$,'23514','receipt relink denied');
select pg_temp.expect_error($q$update public.contributions set program_id='70000000-0000-4000-8000-000000000002'$q$,'23503','program/event types enforced');
select pg_temp.expect_error($q$update public.contributions set currency='USD'$q$,'23514','CAD only');
select pg_temp.expect_error($q$update public.contributions set agreement_end='2023-01-01'$q$,'23514','agreement date order');
select pg_temp.expect_error($q$select public.giving_summary(null)$q$,'22023','null year denied');
insert into public.giving_document_links(contribution_id,label,url) values('71000000-0000-4000-8000-000000000001','Synthetic agreement','https://example.test/agreement');
select pg_temp.expect_error($q$update public.giving_document_links set url='javascript:alert(1)'$q$,'23514','unsafe document URLs denied');
select pg_temp.expect_error($q$delete from public.cash_receipts$q$,'42501','receipt deletion disabled');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',false);
select pg_temp.assert_true((select count(*)=2 from public.contribution_details),'staff reads invoker view');
select pg_temp.expect_error($q$insert into public.contributions(contribution_date,amount,contribution_type) values('2025-01-01',5,'Cash')$q$,'42501','staff financial create denied');
with changed as(update public.cash_receipts set amount=1 returning id) select pg_temp.assert_true((select count(*)=0 from changed),'staff receipt edit denied');
with changed as(update public.contributions set amount=1 returning id) select pg_temp.assert_true((select count(*)=0 from changed),'staff contribution edit denied');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000005',false);
select pg_temp.assert_true((select count(*)=2 from public.contribution_details),'viewer reads');
with changed as(update public.funding_initiatives set name='Denied' returning id) select pg_temp.assert_true((select count(*)=0 from changed),'viewer initiative edit denied');
select pg_temp.expect_error($q$insert into public.giving_document_links(contribution_id,label,url) values('71000000-0000-4000-8000-000000000001','Denied','https://example.test')$q$,'42501','viewer link create denied');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000006',false);
select pg_temp.assert_true((select count(*)=0 from public.contribution_details),'inactive invoker view denied');
select pg_temp.assert_true((public.giving_summary(2025)->>'lifetime_cash')::numeric=0,'summary cannot bypass inactive RLS');
reset role;
set role anon;
select pg_temp.expect_error($q$select * from public.contributions$q$,'42501','anonymous financial access denied');
select pg_temp.expect_error($q$select public.giving_summary(2025)$q$,'42501','anonymous RPC denied');
reset role;
